using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json.Nodes;
using WindWaker.Installer;

var suite = new (string, Action)[] {
 ("Configured external dump installs without modifying source", () => {using var f=new Fixture();var external=Path.Combine(f.Base,"Dump externo ç");Directory.Move(Path.Combine(f.Game.DataRoot,"game"),external);File.WriteAllText(Path.Combine(f.Game.DataRoot,"install.json"),new JsonObject{["game_dir"]=external}.ToJsonString());var g=InstallerEngine.Resolve(f.Root);Check(g!=null,"External dump rejected");Check(g!.Pack==Path.Combine(external,"content","Common","Pack","permanent_2d_UsEnglish.pack"),"Wrong pack");f.Engine.Install(g,false);Check(File.Exists(Path.Combine(f.Game.Mod,"manifest.json")),"Wrong mod destination");Check(File.ReadAllBytes(g.Pack).SequenceEqual(Fixture.Original),"Source modified");}),
 ("Relative game_dir works from data and renamed launcher", () => {using var f=new Fixture();Directory.Move(Path.Combine(f.Game.DataRoot,"game"),Path.Combine(f.Root,"Meus arquivos"));File.Move(Path.Combine(f.Root,"Wind Waker HD.exe"),Path.Combine(f.Root,"Jogar.exe"));File.WriteAllText(Path.Combine(f.Game.DataRoot,"install.json"),new JsonObject{["game_dir"]="../Meus arquivos"}.ToJsonString());Check(InstallerEngine.Resolve(f.Game.DataRoot)?.Root==f.Root,"Relative path rejected");}),
 ("Invalid configured path never falls back to stale game folder", () => {using var f=new Fixture();File.WriteAllText(Path.Combine(f.Game.DataRoot,"install.json"),"{\"game_dir\":\"missing\"}");Check(InstallerEngine.Resolve(f.Root)==null,"Stale pack accepted");}),

 ("Recognizes root, data, game and executable paths", () => { using var f=new Fixture(); foreach(var p in new[]{f.Root,Path.Combine(f.Root,"data"),Path.Combine(f.Root,"data","game"),Path.Combine(f.Root,"Wind Waker HD.exe")}) Check(InstallerEngine.Resolve(p)?.Root==f.Root,"Wrong normalized root"); Check(InstallerEngine.Resolve(f.Base)==null,"Unrelated folder accepted"); }),
 ("Finds a custom Recomp Launcher installation and deduplicates", () => {using var f=new Fixture();var json=Path.Combine(f.Base,"library.json");File.WriteAllText(json,new JsonObject { ["installed"]=new JsonObject{["zeldawwhdrecomp"]=new JsonObject{["path"]=f.Root}}}.ToJsonString());var r=InstallerEngine.Detect(new[]{f.Root,Path.Combine(f.Root,"data")},json).ToList();Check(r.Count==1&&r[0].Root==f.Root,"Detection failed");}),
 ("Installs offline while preserving original pack, saves and other mods", () => {using var f=new Fixture();f.Engine.Install(f.Game,false);Check(File.ReadAllBytes(Path.Combine(f.Game.Mod,"content","Common","Pack","permanent_2d_UsEnglish.pack")).SequenceEqual(Fixture.Translated),"Wrong payload");Check(File.ReadAllBytes(f.Game.Pack).SequenceEqual(Fixture.Original),"Original changed");Check(File.ReadAllText(f.Save)=="SAVE-DO-NOT-CHANGE","Save changed");var j=f.Profiles();Check((bool)j["profiles"]!["Default"]!["enabled"]!["another-mod"]!,"Other mod disabled");Check((bool)j["profiles"]!["Default"]!["enabled"]!["wind-waker-ptbr"]!,"Translation not enabled");Check(File.Exists(Path.Combine(f.Game.Backup,"Original","permanent_2d_UsEnglish.pack")),"No original backup");}),
 ("Repeated install never replaces the initial backup", () => {using var f=new Fixture();f.Engine.Install(f.Game,false);var p=Path.Combine(f.Game.Backup,"Original","profiles.json");var before=File.ReadAllBytes(p);var time=File.GetLastWriteTimeUtc(p);f.Engine.Install(f.Game,false);Check(File.ReadAllBytes(p).SequenceEqual(before)&&File.GetLastWriteTimeUtc(p)==time,"Baseline overwritten");}),
 ("Restore disables translation in all profiles and preserves later mods", () => {using var f=new Fixture();f.Engine.Install(f.Game,false);var j=f.Profiles();j["profiles"]!["Default"]!["enabled"]!["new-mod"]=true;j["profiles"]!["Other"]=new JsonObject{["enabled"]=new JsonObject{["wind-waker-ptbr"]=true,["another"]=true}};File.WriteAllText(f.Game.Profiles,j.ToJsonString());f.Engine.Restore(f.Game,false);j=f.Profiles();Check(!(bool)j["profiles"]!["Default"]!["enabled"]!["wind-waker-ptbr"]!,"Still enabled");Check(!(bool)j["profiles"]!["Other"]!["enabled"]!["wind-waker-ptbr"]!,"Other profile still enabled");Check((bool)j["profiles"]!["Default"]!["enabled"]!["new-mod"]!,"New mod lost");Check((bool)j["profiles"]!["Other"]!["enabled"]!["another"]!,"Other profile lost");Check(!Directory.Exists(f.Game.Mod),"Translation still active on disk");Check(File.ReadAllText(f.Save)=="SAVE-DO-NOT-CHANGE","Save changed");f.Engine.Restore(f.Game,false);}),
 ("Rejects a different original game before changing profiles", () => {using var f=new Fixture();var before=File.ReadAllText(f.Game.Profiles);File.WriteAllText(f.Game.Pack,"different version");Throws(()=>f.Engine.Install(f.Game,false));Check(File.ReadAllText(f.Game.Profiles)==before&&!Directory.Exists(f.Game.Mod),"Changed files before compatibility check");}),
 ("Rejects a corrupted embedded translation", () => {using var f=new Fixture();var e=new InstallerEngine(Fixture.Zip(),new string('0',64),Fixture.Hash(Fixture.Original));Throws(()=>e.Install(f.Game,false));Check(!Directory.Exists(f.Game.Mod),"Corrupt payload installed");}),
 ("Rejects path traversal in the archive", () => {using var f=new Fixture();var e=new InstallerEngine(Fixture.Zip(true),Fixture.Hash(Fixture.Translated),Fixture.Hash(Fixture.Original));Throws(()=>e.Install(f.Game,false));Check(!File.Exists(Path.Combine(f.Root,"escaped.txt")),"Archive escaped");}),
 ("Invalid profile JSON is preserved instead of overwritten", () => {using var f=new Fixture();File.WriteAllText(f.Game.Profiles,"{broken");Throws(()=>f.Engine.Install(f.Game,false));Check(File.ReadAllText(f.Game.Profiles)=="{broken"&&!Directory.Exists(f.Game.Mod),"Malformed profile overwritten");}),
 ("Creates an active default profile on a fresh installation", () => {using var f=new Fixture();File.Delete(f.Game.Profiles);f.Engine.Install(f.Game,false);Check((string)f.Profiles()["active"]! =="Default","No default profile");Check((bool)f.Profiles()["profiles"]!["Default"]!["enabled"]!["wind-waker-ptbr"]!,"Not activated");}),
 ("Rolls back a mod replacement if profile commit fails", () => {using var f=new Fixture();Directory.CreateDirectory(f.Game.Mod);File.WriteAllText(Path.Combine(f.Game.Mod,"old.txt"),"previous-mod");File.SetAttributes(f.Game.Profiles,FileAttributes.ReadOnly);try{Throws(()=>f.Engine.Install(f.Game,false));Check(File.ReadAllText(Path.Combine(f.Game.Mod,"old.txt"))=="previous-mod","Previous mod lost on rollback");}finally{File.SetAttributes(f.Game.Profiles,FileAttributes.Normal);}}),
 ("Rollback restores absent profiles after a post-commit failure", () => {using var f=new Fixture();File.Delete(f.Game.Profiles);Throws(()=>f.Engine.Install(f.Game,false,_=>{if(Directory.Exists(f.Game.Mod)&&File.Exists(f.Game.Profiles))throw new IOException("Progress reporting failed after commit");}));Check(!File.Exists(f.Game.Profiles),"A newly created active profile was left behind");Check(!Directory.Exists(f.Game.Mod),"Mod was left behind");Check(File.ReadAllText(f.Save)=="SAVE-DO-NOT-CHANGE","Save changed");}),
 ("Rejects malformed enabled-mod data without losing it", () => {using var f=new Fixture();var j=f.Profiles();j["profiles"]!["Default"]!["enabled"]=new JsonArray("precious-mod-state");var original=j.ToJsonString();File.WriteAllText(f.Game.Profiles,original);Throws(()=>f.Engine.Install(f.Game,false));Check(File.ReadAllText(f.Game.Profiles)==original,"Malformed user data was replaced");Check(!Directory.Exists(f.Game.Mod),"Mod installed over invalid profile");}),
 ("Refuses linked mod folders", () => {using var f=new Fixture();var elsewhere=Path.Combine(f.Base,"other-folder");Directory.CreateDirectory(elsewhere);Directory.CreateDirectory(Path.GetDirectoryName(f.Game.Mod)!);try{Directory.CreateSymbolicLink(f.Game.Mod,elsewhere);}catch(Exception e)when(e is UnauthorizedAccessException||(e.HResult&0xffff)==1314){Fixture.Skipped++;Console.WriteLine("  SKIP: OS does not permit symbolic links");return;}Throws(()=>f.Engine.Install(f.Game,false));Check(!File.Exists(Path.Combine(elsewhere,"manifest.json")),"Wrote through symbolic link");}),
 ("Parses release versions", () => {Check(Updater.ParseVersion("v1.0.7")==new Version(1,0,7),"v prefix");Check(Updater.ParseVersion("1.0")==Updater.ParseVersion("1.0.0"),"1.0 vs 1.0.0");Check(Updater.ParseVersion("1.1.0-beta")==new Version(1,1,0),"suffix");Check(Updater.ParseVersion("lixo")==null&&Updater.ParseVersion(null)==null,"garbage accepted");Check(Updater.ParseVersion("1.0.10")>Updater.ParseVersion("1.0.9"),"numeric order");}),
 ("Reads installed translation version from the ModManager", () => {using var f=new Fixture();Check(Updater.InstalledVersion(f.Game)==null,"Version without install");f.Engine.Install(f.Game,false);Check(Updater.InstalledVersion(f.Game)==new Version(1,0,7),"Wrong installed version");}),
 ("Finds a newer release and downloads a verified payload", () => {using var f=new Fixture();var r=Release.Make(Fixture.Zip(false,"1.0.8"));using var http=new HttpClient(r.Handler);var info=Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult();Check(info!=null&&info.Version==new Version(1,0,8),"Release not found");var bytes=Updater.DownloadPayloadAsync(http,info!).GetAwaiter().GetResult();Check(Updater.PayloadVersion(bytes)==new Version(1,0,8),"Wrong payload");}),
 ("Updates an installed translation keeping other mods, saves and backup", () => {using var f=new Fixture();f.Engine.Install(f.Game,false);var zip=Fixture.Zip(false,"1.0.8");var r=Release.Make(zip);using var http=new HttpClient(r.Handler);var info=Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult()!;var bytes=Updater.DownloadPayloadAsync(http,info).GetAwaiter().GetResult();new InstallerEngine(bytes,info.PackSha256,Fixture.Hash(Fixture.Original)).Install(f.Game,false);Check(Updater.InstalledVersion(f.Game)==new Version(1,0,8),"Not updated");Check((bool)f.Profiles()["profiles"]!["Default"]!["enabled"]!["another-mod"]!,"Other mod lost");Check((bool)f.Profiles()["profiles"]!["Default"]!["enabled"]!["wind-waker-ptbr"]!,"Translation disabled");Check(File.ReadAllText(f.Save)=="SAVE-DO-NOT-CHANGE","Save changed");Check(File.ReadAllBytes(f.Game.Pack).SequenceEqual(Fixture.Original),"Original changed");}),
 ("Rejects a payload whose hash does not match", () => {var zip=Fixture.Zip(false,"1.0.8");var r=Release.Make(zip,payloadBytes:Fixture.Zip(false,"1.0.8").Concat(new byte[]{0}).ToArray(),declaredSize:zip.Length+1);using var http=new HttpClient(r.Handler);var info=Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult()!;Throws(()=>Updater.DownloadPayloadAsync(http,info).GetAwaiter().GetResult());var tampered=(byte[])zip.Clone();tampered[tampered.Length/2]^=0xFF;var r2=Release.Make(zip,payloadBytes:tampered);using var http2=new HttpClient(r2.Handler);var info2=Updater.FetchLatestAsync(http2,Release.Api,Release.Prefix).GetAwaiter().GetResult()!;Throws(()=>Updater.DownloadPayloadAsync(http2,info2).GetAwaiter().GetResult());}),
 ("Rejects a release whose payload version differs from the tag", () => {var r=Release.Make(Fixture.Zip(false,"1.0.8"),tag:"v1.0.9");using var http=new HttpClient(r.Handler);Check(Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult()==null,"Mismatched tag accepted");var r2=Release.Make(Fixture.Zip(false,"1.0.7"),manifestVersion:"1.0.8");using var http2=new HttpClient(r2.Handler);var info=Updater.FetchLatestAsync(http2,Release.Api,Release.Prefix).GetAwaiter().GetResult()!;Throws(()=>Updater.DownloadPayloadAsync(http2,info).GetAwaiter().GetResult());}),
 ("Refuses update files hosted outside the translation repository", () => {var r=Release.Make(Fixture.Zip(false,"1.0.8"),host:"https://evil.example/releases/download/");using var http=new HttpClient(r.Handler);Check(Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult()==null,"Foreign host accepted");}),
 ("Ignores releases without update manifest and survives network errors", () => {var r=Release.Make(Fixture.Zip(false,"1.0.8"),withManifest:false);using var http=new HttpClient(r.Handler);Check(Updater.FetchLatestAsync(http,Release.Api,Release.Prefix).GetAwaiter().GetResult()==null,"Release without update.json accepted");using var down=new HttpClient(new Release.Fake(_=>null));Throws(()=>Updater.FetchLatestAsync(down,Release.Api,Release.Prefix).GetAwaiter().GetResult());})
};
int failures=0;foreach(var(name,test)in suite){try{var skipped=Fixture.Skipped;test();if(skipped==Fixture.Skipped)Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
Console.WriteLine($"{suite.Length-failures-Fixture.Skipped} passed; {Fixture.Skipped} skipped; {failures} failed");return failures==0?0:1;
static void Check(bool b,string why){if(!b)throw new Exception(why);}
static void Throws(Action a){try{a();}catch(Exception e)when(e is not NotImplementedException){return;}throw new Exception("Expected safe rejection");}

sealed class Fixture:IDisposable {
 public static int Skipped;
 public static readonly byte[] Original=Encoding.UTF8.GetBytes("SARC original test data");
 public static readonly byte[] Translated=Encoding.UTF8.GetBytes("SARC tradução test data");
 public string Base=Path.Combine(Path.GetTempPath(),"WWHD-Installer-Tests",Guid.NewGuid().ToString("N"));
 public string Root; public GameLocation Game; public InstallerEngine Engine; public string Save;
 public Fixture(){Root=Path.Combine(Base,"Meu jogo com espaços");Game=new GameLocation(Root,Path.Combine(Root,"data"));Directory.CreateDirectory(Path.GetDirectoryName(Game.Pack)!);File.WriteAllBytes(Game.Pack,Original);File.WriteAllText(Path.Combine(Root,"Wind Waker HD.exe"),"fixture");Directory.CreateDirectory(Game.Manager);File.WriteAllText(Game.Profiles,"{\"active\":\"Default\",\"profiles\":{\"Default\":{\"enabled\":{\"another-mod\":true}}},\"native_trust\":{\"custom\":true}}");Save=Path.Combine(Game.DataRoot,"save","user","cking.sav");Directory.CreateDirectory(Path.GetDirectoryName(Save)!);File.WriteAllText(Save,"SAVE-DO-NOT-CHANGE");Engine=new InstallerEngine(Zip(),Hash(Translated),Hash(Original));}
 public JsonObject Profiles()=>JsonNode.Parse(File.ReadAllText(Game.Profiles))!.AsObject();
 public static string Hash(byte[] b)=>Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();
 public static byte[] Zip(bool escape=false,string version="1.0.7"){using var m=new MemoryStream();using(var z=new ZipArchive(m,ZipArchiveMode.Create,true)){using(var s=z.CreateEntry("manifest.json").Open()){var b=Encoding.UTF8.GetBytes("{\"id\":\"wind-waker-ptbr\",\"kind\":\"content\",\"version\":\""+version+"\"}");s.Write(b);}using(var s=z.CreateEntry("content/Common/Pack/permanent_2d_UsEnglish.pack").Open())s.Write(Translated);if(escape){using var s=z.CreateEntry("../../escaped.txt").Open();s.WriteByte(1);}}return m.ToArray();}
 public void Dispose(){if(Directory.Exists(Base)){foreach(var f in Directory.EnumerateFiles(Base,"*",SearchOption.AllDirectories))File.SetAttributes(f,FileAttributes.Normal);Directory.Delete(Base,true);}}
}

static class Release {
 public static readonly Uri Api=new("https://api.test/releases/latest");
 public const string Prefix="https://github.test/repo/releases/download/";
 public sealed class Fake(Func<Uri,byte[]?> respond):HttpMessageHandler {
  protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){var body=respond(r.RequestUri!);if(body==null)throw new HttpRequestException("offline");return Task.FromResult(new HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new ByteArrayContent(body)});}
 }
 public sealed record Made(HttpMessageHandler Handler);
 public static Made Make(byte[] zip,string tag="",byte[]? payloadBytes=null,long declaredSize=0,string? manifestVersion=null,string host=Prefix,bool withManifest=true) {
  var version=Updater.PayloadVersion(zip)!.ToString(3);if(tag=="")tag="v"+version;
  var name="payload-v"+version+".zip";
  var update=Encoding.UTF8.GetBytes(new JsonObject{["version"]=manifestVersion??version,["payload"]=name,["payload_sha256"]=Fixture.Hash(zip),["payload_size"]=declaredSize>0?declaredSize:zip.Length,["pack_sha256"]=Fixture.Hash(Fixture.Translated)}.ToJsonString());
  var assets=new JsonArray();if(withManifest)assets.Add(new JsonObject{["name"]="update.json",["browser_download_url"]=host+tag+"/update.json"});assets.Add(new JsonObject{["name"]=name,["browser_download_url"]=host+tag+"/"+name});
  var releaseJson=Encoding.UTF8.GetBytes(new JsonObject{["tag_name"]=tag,["assets"]=assets}.ToJsonString());
  return new Made(new Fake(u=>u==Api?releaseJson:u.AbsolutePath.EndsWith("update.json")?update:u.AbsolutePath.EndsWith(name)?(payloadBytes??zip):null));
 }
}
